<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>2048</title>
  <style>
    :root {
      color-scheme: dark;
      font-family: Arial, Helvetica, sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      background: #111318;
      color: #f5f5f5;
    }

    main {
      width: min(92vw, 500px);
    }

    header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      margin-bottom: 16px;
    }

    h1 {
      margin: 0;
      font-size: 3rem;
      line-height: 1;
    }

    .controls {
      display: flex;
      align-items: stretch;
      gap: 10px;
    }

    .score-box {
      min-width: 92px;
      padding: 8px 14px;
      border-radius: 8px;
      background: #292d35;
      text-align: center;
    }

    .score-label {
      display: block;
      margin-bottom: 3px;
      color: #adb3bf;
      font-size: 0.72rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    #score {
      font-size: 1.35rem;
      font-weight: 800;
    }

    #reset {
      border: 0;
      border-radius: 8px;
      padding: 0 16px;
      background: #f0a43b;
      color: #17120b;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
    }

    #reset:hover {
      background: #ffb650;
    }

    #reset:focus-visible {
      outline: 3px solid #fff;
      outline-offset: 3px;
    }

    #board {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 10px;
      aspect-ratio: 1;
      padding: 10px;
      border-radius: 12px;
      background: #292d35;
      box-shadow: 0 18px 45px rgb(0 0 0 / 35%);
    }

    .tile {
      display: grid;
      place-items: center;
      min-width: 0;
      border-radius: 8px;
      background: #3a3f49;
      color: #f8f8f8;
      font-size: clamp(1.35rem, 7vw, 2.25rem);
      font-weight: 900;
      user-select: none;
    }

    .tile[data-value="0"] {
      color: transparent;
    }

    .tile[data-value="2"] { background: #454b57; }
    .tile[data-value="4"] { background: #565064; }
    .tile[data-value="8"] { background: #bd6737; }
    .tile[data-value="16"] { background: #c95436; }
    .tile[data-value="32"] { background: #c33e3e; }
    .tile[data-value="64"] { background: #a9293f; }
    .tile[data-value="128"] { background: #b58b2f; font-size: clamp(1.15rem, 6vw, 1.9rem); }
    .tile[data-value="256"] { background: #aa7625; font-size: clamp(1.15rem, 6vw, 1.9rem); }
    .tile[data-value="512"] { background: #90611f; font-size: clamp(1.15rem, 6vw, 1.9rem); }
    .tile[data-value="1024"] { background: #79521c; font-size: clamp(0.95rem, 5vw, 1.55rem); }
    .tile[data-value="2048"] { background: #e0a31e; color: #17120b; font-size: clamp(0.95rem, 5vw, 1.55rem); }
  </style>
</head>
<body>
  <main>
    <header>
      <h1>2048</h1>
      <div class="controls">
        <div class="score-box">
          <span class="score-label">Score</span>
          <span id="score">0</span>
        </div>
        <button id="reset" type="button">New Game</button>
      </div>
    </header>
    <div id="board" aria-label="2048 board"></div>
  </main>

  <script>
    (() => {
      "use strict";

      const size = 4;
      const boardElement = document.getElementById("board");
      const scoreElement = document.getElementById("score");
      const resetButton = document.getElementById("reset");

      let grid = createEmptyBoard();
      let currentScore = 0;

      function createEmptyBoard() {
        return Array.from({ length: size }, () => Array(size).fill(0));
      }

      function render() {
        boardElement.replaceChildren();

        for (const row of grid) {
          for (const value of row) {
            const tile = document.createElement("div");
            tile.className = "tile";
            tile.dataset.value = String(value);
            tile.textContent = value === 0 ? "" : String(value);
            boardElement.appendChild(tile);
          }
        }

        scoreElement.textContent = String(currentScore);
      }

      function spawnTile() {
        const emptyCells = [];

        for (let row = 0; row < size; row++) {
          for (let column = 0; column < size; column++) {
            if (grid[row][column] === 0) {
              emptyCells.push([row, column]);
            }
          }
        }

        if (emptyCells.length === 0) return false;

        const [row, column] =
          emptyCells[Math.floor(Math.random() * emptyCells.length)];
        grid[row][column] = Math.random() < 0.9 ? 2 : 4;
        return true;
      }

      function mergeLine(line) {
        const values = line.filter(value => value !== 0);
        const result = [];
        let scoreGained = 0;

        for (let index = 0; index < values.length; index++) {
          if (
            index + 1 < values.length &&
            values[index] === values[index + 1]
          ) {
            const mergedValue = values[index] * 2;
            result.push(mergedValue);
            scoreGained += mergedValue;
            index++;
          } else {
            result.push(values[index]);
          }
        }

        while (result.length < size) result.push(0);
        return { line: result, scoreGained };
      }

      function linesFor(direction) {
        const lines = [];

        for (let outer = 0; outer < size; outer++) {
          const line = [];

          for (let inner = 0; inner < size; inner++) {
            let row;
            let column;

            if (direction === "left") {
              row = outer;
              column = inner;
            } else if (direction === "right") {
              row = outer;
              column = size - 1 - inner;
            } else if (direction === "up") {
              row = inner;
              column = outer;
            } else {
              row = size - 1 - inner;
              column = outer;
            }

            line.push(grid[row][column]);
          }

          lines.push(line);
        }

        return lines;
      }

      function boardFromLines(lines, direction) {
        const next = createEmptyBoard();

        for (let outer = 0; outer < size; outer++) {
          for (let inner = 0; inner < size; inner++) {
            let row;
            let column;

            if (direction === "left") {
              row = outer;
              column = inner;
            } else if (direction === "right") {
              row = outer;
              column = size - 1 - inner;
            } else if (direction === "up") {
              row = inner;
              column = outer;
            } else {
              row = size - 1 - inner;
              column = outer;
            }

            next[row][column] = lines[outer][inner];
          }
        }

        return next;
      }

      function boardsEqual(first, second) {
        return first.every((row, rowIndex) =>
          row.every(
            (value, columnIndex) => value === second[rowIndex][columnIndex]
          )
        );
      }

      function move(direction) {
        if (!["left", "right", "up", "down"].includes(direction)) {
          return false;
        }

        let scoreGained = 0;
        const mergedLines = linesFor(direction).map(line => {
          const merged = mergeLine(line);
          scoreGained += merged.scoreGained;
          return merged.line;
        });

        const next = boardFromLines(mergedLines, direction);

        if (boardsEqual(grid, next)) {
          return false;
        }

        grid = next;
        currentScore += scoreGained;
        spawnTile();
        render();
        return true;
      }

      function reset() {
        grid = createEmptyBoard();
        currentScore = 0;
        spawnTile();
        spawnTile();
        render();
      }

      function setBoard(arr) {
        if (
          !Array.isArray(arr) ||
          arr.length !== size ||
          arr.some(row => !Array.isArray(row) || row.length !== size) ||
          arr.some(row =>
            row.some(value => !Number.isFinite(value) || value < 0)
          )
        ) {
          throw new TypeError("Board must be a 4x4 array of non-negative numbers.");
        }

        grid = arr.map(row => row.slice());
        render();
      }

      window.game = {
        size,
        reset,
        move,
        board: () => grid.map(row => row.slice()),
        setBoard,
        score: () => currentScore
      };

      resetButton.addEventListener("click", reset);

      document.addEventListener("keydown", event => {
        const directions = {
          ArrowLeft: "left",
          ArrowRight: "right",
          ArrowUp: "up",
          ArrowDown: "down"
        };

        const direction = directions[event.key];
        if (direction) {
          event.preventDefault();
          move(direction);
        }
      });

      reset();
    })();
  </script>
</body>
</html>
